#!/usr/bin/env bash
# step98 — Batch 1: de-duplicate product.ejs (the doubled MAC field/CSS/JS -> one)
# and stop /track (order.ejs) showing raw credentials — point to the login-gated
# dashboard page instead. Idempotent; rolls back both views.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step98-$TS
mkdir -p "$BAK/views"
cp "$APP/views/product.ejs" "$BAK/views/product.ejs"
cp "$APP/views/order.ejs" "$BAK/views/order.ejs"
restore(){ echo "!! rollback"; cp "$BAK/views/product.ejs" "$APP/views/product.ejs"; cp "$BAK/views/order.ejs" "$APP/views/order.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> overwrite product.ejs (single MAC field, de-duplicated)"
base64 -d > "$APP/views/product.ejs" <<'B64'

B64

echo "==> patch order.ejs (/track hides credentials; links to dashboard)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/views/order.ejs'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('View my details securely')>=0){ console.log('   order.ejs already patched'); }
else {
  const a="  <% if (o.delivered_credentials) { %>\n  <div class=\"card\">\n    <h1 style=\"font-size:18px\">Your order details</h1>\n    <div class=\"creds\"><%= o.delivered_credentials %></div>\n    <p class=\"fine\">Keep these safe. A copy has also been sent to your email and WhatsApp.</p>\n  </div>\n  <% } %>";
  if(s.indexOf(a)<0){ console.error('!! order.ejs credentials block anchor not found'); process.exit(2); }
  const n="  <% if (o.delivered_credentials) { %>\n  <div class=\"card\">\n    <h1 style=\"font-size:18px\">Your order is ready</h1>\n    <p class=\"lead\" style=\"margin-bottom:10px\">For your security, your login details are shown only inside your account.</p>\n    <div class=\"acts\">\n      <a class=\"btn\" href=\"/account/order/<%= o.order_no %>/credentials\">View my details securely</a>\n      <a class=\"btn btn-ghost\" href=\"/login?next=<%= encodeURIComponent('/account/order/'+o.order_no+'/credentials') %>\">Sign in</a>\n    </div>\n    <p class=\"fine\">A copy was also sent to your email and WhatsApp.</p>\n  </div>\n  <% } %>";
  s=s.replace(a,n); fs.writeFileSync(f,s); console.log('   order.ejs patched');
}
NODE

echo "==> ejs compile + restart"
node -e "const ejs=require('ejs'),fs=require('fs');['views/product.ejs','views/order.ejs'].forEach(v=>{ejs.compile(fs.readFileSync('$APP/'+v,'utf8'),{filename:'$APP/'+v});});console.log('   both views compile');"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
trap - ERR
echo "==> step98 OK — single MAC field + /track no longer shows credentials. Backup: $BAK"
